const DATA={"hero": "data:image/jpeg;base64,", "services": [{"name": "CO2 Jet", "desc": "Instant CO2 blast for high impact moments.", "img": "data:image/jpeg;base64,"}, {"name": "Smoke Bubble Machine", "desc": "Bubbles + smoke for a magical atmosphere.", "img": "data:image/jpeg;base64,"}, {"name": "Fire Flame Machine", "desc": "Realistic flame effects that light up the stage.", "img": "data:image/jpeg;base64,"}, {"name": "CO2 Paper Blaster", "desc": "Shoot paper & CO2 for big celebrations.", "img": "data:image/jpeg;base64,"}, {"name": "Smoke Jet Machines", "desc": "Powerful smoke jets for stunning visuals.", "img": "data:image/jpeg;base64,"}]};

/* ================= SETTINGS ================= */
// Inquiry emails are sent to this address (FormSubmit.co - no backend needed)
const RECEIVER_EMAIL = "sarthakgunjal29@gmail.com";
const LOGIN_ID = "admin", LOGIN_PASS = "admin";
/* ============================================ */

const $ = s => document.querySelector(s), $$ = s => document.querySelectorAll(s);

// backgrounds
$$('[data-bg="hero"]').forEach(e => e.style.backgroundImage = `url(${DATA.hero})`);

// service cards
const card = s => `<div class="svc"><div class="pic-wrap"><div class="pic" style="background-image:url(${s.img})"></div></div><h3>${s.name}</h3><p>${s.desc}</p></div>`;
$('#aboutGrid').innerHTML = DATA.services.map(card).join('');
$('#servicesGrid').innerHTML = DATA.services.map(card).join('');
$('#checks').innerHTML = DATA.services.map(s => `<label><input type="checkbox" name="svc" value="${s.name}"> ${s.name}</label>`).join('')
  + `<label><input type="checkbox" name="svc" value="Sound / Lights / Decoration"> Sound / Lights / Decoration</label>`;

// login
function showSite(){ $('#loginPage').classList.add('hidden'); $('#site').classList.remove('hidden'); go('about'); }
const store = {
  get(){ try { return sessionStorage.getItem('tandavLogin'); } catch(e){ return null; } },
  set(){ try { sessionStorage.setItem('tandavLogin','1'); } catch(e){} },
  del(){ try { store.del(); } catch(e){} }
};
if (store.get() === '1') showSite();
$('#loginForm').addEventListener('submit', e => {
  e.preventDefault();
  if ($('#loginId').value.trim().toLowerCase() === LOGIN_ID && $('#loginPass').value.trim() === LOGIN_PASS) {
    store.set(); $('#loginErr').textContent = ''; showSite();
  } else $('#loginErr').textContent = 'Invalid ID or password';
});
$('#logout').addEventListener('click', e => {
  e.preventDefault(); store.del();
  $('#site').classList.add('hidden'); $('#loginPage').classList.remove('hidden'); $('#loginForm').reset();
});

// navigation
function go(page){
  $$('.page').forEach(p => p.classList.toggle('show', p.id === page));
  $$('nav a[data-page]').forEach(a => a.classList.toggle('active', a.dataset.page === page));
  $('#menu').classList.remove('open'); window.scrollTo({top:0,behavior:'smooth'});
  if (page === 'about') countUp();
}
document.addEventListener('click', e => {
  const a = e.target.closest('[data-page]');
  if (a) { e.preventDefault(); go(a.dataset.page); }
});
$('#burger').onclick = () => $('#menu').classList.toggle('open');

// counters
function countUp(){
  $$('[data-count]').forEach(el => {
    const end = +el.dataset.count; let n = 0; const step = Math.max(1, Math.ceil(end / 50));
    const t = setInterval(() => { n = Math.min(end, n + step); el.textContent = n; if (n >= end) clearInterval(t); }, 30);
  });
}

// inquiry -> email
$('#inqForm').addEventListener('submit', async e => {
  e.preventDefault();
  const f = e.target, msg = $('#formMsg'), btn = $('#sendBtn');
  const services = [...$$('input[name=svc]:checked')].map(c => c.value);
  msg.className = 'msg';
  if (!f.checkValidity()) { msg.classList.add('bad'); msg.textContent = 'Please fill all required fields correctly.'; f.reportValidity(); return; }
  if (!services.length) { msg.classList.add('bad'); msg.textContent = 'Please select at least one service.'; return; }

  const fd = new FormData(f);
  fd.delete('svc');
  fd.append('Services Required', services.join(', '));
  fd.append('_subject', 'New Inquiry - Tandav Events (' + f.Name.value + ')');
  fd.append('_template', 'table');
  fd.append('_captcha', 'false');

  btn.disabled = true; btn.textContent = 'Sending...';
  try {
    const r = await fetch('https://formsubmit.co/ajax/' + RECEIVER_EMAIL, { method:'POST', headers:{Accept:'application/json'}, body: fd });
    const d = await r.json();
    if (r.ok && (d.success === true || d.success === 'true')) {
      msg.classList.add('ok'); msg.textContent = '✔ Inquiry sent successfully! We will contact you soon.'; f.reset();
    } else throw new Error(d.message || 'Failed');
  } catch (err) {
    msg.classList.add('bad');
    msg.textContent = 'Could not send. Please open the site via a server/hosting (not file://), check internet, or call +91 8862087966.';
  }
  btn.disabled = false; btn.textContent = 'Submit Inquiry';
});
